 SELECT m.code,d.id FROM (VALUES ('MEDICAL','Medical / Ambulance'),('FIRE','Fire and Rescue'),('FLOOD','Flood / Water Rescue'),('TRAPPED','Search and Rescue'),('COLLAPSE','Search and Rescue'),('COLLAPSE','Fire and Rescue'),('ROAD_ACCIDENT','Medical / Ambulance'),('ROAD_ACCIDENT','Police / Security'),('VIOLENCE','Police / Security'),('LANDSLIDE','Search and Rescue'),('CHEMICAL','Hazardous Materials'),('MISSING','Search and Rescue'),('MISSING','Police / Security'),('BUILDING_DAMAGE','Infrastructure / Utilities'),('BLOCKED_ROAD','Infrastructure / Utilities'),('POWER_OUTAGE','Infrastructure / Utilities'),('PUBLIC_SAFETY','Police / Security'),('OTHER','Disaster Management')) m(code,department) JOIN departments d ON d.name=m.department ON CONFLICT DO NOTHING;
CREATE TRIGGER immutable_announcement_revisions BEFORE UPDATE OR DELETE ON announcement_revisions FOR EACH ROW EXECUTE FUNCTION deny_audit_mutation();
